  root.addEventListener("submit", (event) => {
    if (!event.target.matches("[data-live-form]")) return;
    event.preventDefault();
    // Answers need only the latest queued tap. Moderator commands must all run:
    // each Draw click is a fresh draw, even while a previous request is in flight.
    if (root.dataset.role === "player") pending.length = 0;
    pending.push({ url: event.target.action, body: new FormData(event.target) });
    submit();
  });

