  <%= form_with model: [:moderate, @quiz] do |form| %>
    <%= render "shared/errors", record: @quiz %>
    <div class="field">
      <%= form.label :title, "Title" %>
      <%= form.text_field :title, class: "input", required: true, autofocus: true, placeholder: "e.g. Frontend Fest 2026" %>
    </div>
    <div class="field">
      <%= form.label :number_of_winners, "Number of winners" %>
      <%= form.number_field :number_of_winners, class: "input input--small", min: 1, step: 1, required: true, aria: { describedby: "winners-help" } %>
      <p class="hint" id="winners-help">Prizes to award after the quiz. Only players with points can win.</p>
    </div>
    <div class="buttons">
      <%= form.submit "Save quiz", class: "btn btn--pink" %>
      <%= link_to "Cancel", @quiz.persisted? ? moderate_quiz_path(@quiz) : moderate_root_path, class: "btn btn--ghost" %>
    </div>
  <% end %>
</div>
